"""Order records."""


class Order:
    def __init__(self, customer, amount):
        self.customer = customer
        self.amount = amount

    def __repr__(self):
        return "Order(%r, %r)" % (self.customer, self.amount)


ROWS = [('birch', 51), ('corvo', 46), ('delta', 28), ('acme', 53), ('birch', 16)]


def load_orders():
    """Yield the stored orders one at a time."""
    for customer, amount in ROWS:
        yield Order(customer, amount)

