"""Parsing orders from text."""
from orders import Order


def _parse_line(line):
    customer, amount = line.split(",")
    return Order(customer.strip(), int(amount))


def parse_orders(text):
    """Parse lines of 'customer,amount' into Order records. Blank lines are skipped."""
    out = []
    line = ""
    for ch in text:
        if ch == "\n":
            if line.strip():
                out.append(_parse_line(line))
            line = ""
        else:
            line += ch
    return out


def largest_amount(orders):
    """Return the largest amount, or None when there are no orders."""
    values = [x.amount for x in orders]
    return max(values) if values else None

